scriptdefs
= Route104_PrettyPetalFlowerShop_EventScript_RandomBerryGirl
lock
faceplayer
dotimebasedevents
goto_if_set FLAG_DAILY_FLOWER_SHOP_RECEIVED_BERRY Route104_PrettyPetalFlowerShop_EventScript_AlreadyReceivedBerry
msgbox	Ich versuche, wie meine großen Schwestern zu sein. Ich züchte auch Blumen!Hier, bitte! Das ist für dich!
random 8
addvar VAR_RESULT FIRST_BERRY_INDEX
giveitem VAR_RESULT
goto_if_eq VAR_RESULT 0 Common_EventScript_ShowBagIsFull
setflag FLAG_DAILY_FLOWER_SHOP_RECEIVED_BERRY
msgbox	Du kannst eine BERRY einpflanzen und großziehen, oder du lässt sie ein POKéMON tragen.Aber jetzt gibt es eine Maschine, die verschiedene BERRIES mischt und daraus Bonbons für POKéMON macht.So ein Bonbon hätte ich auch gern.
release
end
= Route104_PrettyPetalFlowerShop_EventScript_AlreadyReceivedBerry
msgbox	Du kannst eine BERRY einpflanzen und großziehen, oder du lässt sie ein POKéMON tragen.Aber jetzt gibt es eine Maschine, die verschiedene BERRIES mischt und daraus Bonbons für POKéMON macht.So ein Bonbon hätte ich auch gern.
release
end
= Route104_PrettyPetalFlowerShop_EventScript_WailmerPailGirl
lock
faceplayer
goto_if_unset FLAG_RECEIVED_WAILMER_PAIL Route104_PrettyPetalFlowerShop_EventScript_GiveWailmerPail
msgbox	Während BERRY-Pflanzen wachsen, gieß sie mit dem WAILMER PAIL.Oh, noch etwas.Wenn du BERRIES eine Weile nicht pflückst, fallen sie zu Boden. Aber sie sprießen wieder.Ist das nicht toll? Es ist, als hätten sie einen Lebenswillen.
release
end
= Route104_PrettyPetalFlowerShop_EventScript_GiveWailmerPail
msgbox	Hallo!Je mehr Aufmerksamkeit du Blumen schenkst, desto schöner blühen sie.Du wirst es lieben, Blumen zu pflegen. Da bin ich mir sicher. Das hier kannst du haben.
giveitem ITEM_WAILMER_PAIL
msgbox	Während BERRY-Pflanzen wachsen, gieß sie mit dem WAILMER PAIL.Oh, noch etwas.Wenn du BERRIES eine Weile nicht pflückst, fallen sie zu Boden. Aber sie sprießen wieder.Ist das nicht toll? Es ist, als hätten sie einen Lebenswillen.
setflag FLAG_RECEIVED_WAILMER_PAIL
release
end
= Route104_PrettyPetalFlowerShop_EventScript_ShopOwner
lock
faceplayer
goto_if_set FLAG_TEMP_1 Route104_PrettyPetalFlowerShop_EventScript_SellDecorations
msgbox	Hallo!Das hier ist der PRETTY PETAL Blumenladen. Wir verbreiten Blumen in der ganzen Welt!
goto_if_set FLAG_MET_PRETTY_PETAL_SHOP_OWNER Route104_PrettyPetalFlowerShop_EventScript_AlreadyMet
setflag FLAG_MET_PRETTY_PETAL_SHOP_OWNER
msgboxyesno	Your name is?PLAYER. That's a nice name.PLAYER, would you like to learn about BERRIES?
call_if_eq VAR_RESULT YES Route104_PrettyPetalFlowerShop_EventScript_ExplainBerries
call_if_eq VAR_RESULT NO Route104_PrettyPetalFlowerShop_EventScript_DontExplainBerries
release
end
= Route104_PrettyPetalFlowerShop_EventScript_DontExplainBerries
msgbox	Blumen bringen den Menschen so viel Freude, findest du nicht?
return
= Route104_PrettyPetalFlowerShop_EventScript_ExplainBerries
msgbox	BERRIES wachsen auf Bäumen, die nur in weichem, lockerem Boden gedeihen.Wenn du dir ein paar BERRIES nimmst, pflanz auf jeden Fall wieder eine in den lockeren Boden.Eine gepflanzte BERRY sprießt bald, wächst zu einer Pflanze heran, blüht wunderschön und trägt dann wieder BERRIES.Ich möchte die ganze weite Welt voller schöner Blumen sehen. Das ist mein Traum.Bitte hilf mir, PLAYER. Pflanz BERRIES und bring mehr Blumen in die Welt.
return
= Route104_PrettyPetalFlowerShop_EventScript_AlreadyMet
msgboxyesno	PLAYER, would you like to learn about BERRIES?
call_if_eq VAR_RESULT YES Route104_PrettyPetalFlowerShop_EventScript_ExplainBerries
call_if_eq VAR_RESULT NO Route104_PrettyPetalFlowerShop_EventScript_DontExplainBerries
release
end
= Route104_PrettyPetalFlowerShop_EventScript_SellDecorations
msgbox	PLAYER, willkommen!Was kann ich für dich tun?
waitmessage
pokemartdecoration2 Route104_PrettyPetalFlowerShop_Pokemart_Plants
msgbox	Bitte komm wieder!
release
end
